//! 🧪️ Same canonical typed Fault streams into original native pages with independent physical receipts.
use super::*;
use crate::{CancelToken,JobPayloadAuthority,StepBudget,logical_now_us};
use semio_framework_diagnostic::Fault;
use semio_framework_value::FromValue;
fn observed<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
fn physical(progress:RetainedCloneProgress,heap:(usize,usize),grant:RetainedCloneGrant){assert!(progress.fits(grant));assert_eq!((progress.retained_capacity_bytes,progress.released_bytes),heap)}
#[test]
fn original_typed_fault_publication_streams_canonical_wire_without_truncation_and_preserves_native_custody(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=law["originalGrant"].as_array().unwrap();let grant=RetainedCloneGrant{maximum_items:p[0].as_u64().unwrap()as usize,maximum_copy_bytes:p[1].as_u64().unwrap()as usize,maximum_capacity_bytes:p[2].as_u64().unwrap()as usize,maximum_release_bytes:p[3].as_u64().unwrap()as usize,maximum_depth:p[4].as_u64().unwrap()as usize};
 let canonical:serde_json::Value=serde_json::from_str(include_str!("../../../../../⚠️diagnostic/🧫️fixtures/🧯️fault/🔣️.json")).unwrap();let mut rows=canonical["cases"].as_array().unwrap().clone();let mut long=rows[1].clone();long["id"]=serde_json::json!("original-long-window");long["input"]["message"]=serde_json::json!("🧩\\\"\n".repeat(2049));long["expected"]["message"]=long["input"]["message"].clone();rows.push(long);
 for row in &rows{let fault=Fault::from_value(serde_json::from_value(row["input"].clone()).unwrap()).unwrap();let foreign=Fault::from_value(serde_json::from_value(row["input"].clone()).unwrap()).unwrap();let fault_pointer=std::ptr::addr_of!(fault);let text_pointer=fault.message.as_ptr();
  for cut in [0,1,257,usize::MAX]{
   let operation=OperationId(99733);let generation=Generation(17);let((cancel,birth),heap)=observed(||CancelToken::admit_root(grant).unwrap().unwrap());physical(birth,heap,grant);let mut born=heap.0;let mut released=heap.1;let((mut authority,birth),heap)=observed(||JobPayloadAuthority::admit(operation,generation,grant).unwrap().unwrap());physical(birth,heap,grant);born+=heap.0;released+=heap.1;
   let(mut publication,heap)=observed(RetainedFaultPublication::new);assert_eq!(heap,(0,0));let original_header=std::ptr::addr_of!(publication);let window_pointer=publication.buffer.as_ptr();let mut turns=0;let mut copied=0;let mut sequence=0;let mut descriptor=None;
   while descriptor.is_none()&&turns<cut{
    let mut receipt=Default::default();let cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let(demand,heap)=observed(||publication.advance_demands(&fault,&cx).unwrap());assert_eq!(heap,(0,0));drop(cx);
    for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(demand.copy_bytes>0).then(||RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes-1,..grant}),(demand.capacity_bytes>0).then(||RetainedCloneGrant{maximum_capacity_bytes:0,..grant}),(demand.depth>0).then(||RetainedCloneGrant{maximum_depth:demand.depth-1,..grant})].into_iter().flatten(){let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,denied),&cancel,logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let(value,heap)=observed(||publication.advance_from_fault(&fault,&mut cx).unwrap().map(JobOutcomeBorrow::into_descriptor));assert!(value.is_none());assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),Default::default());}
    if publication.binding.is_some(){let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let(value,heap)=observed(||publication.advance_from_fault(&foreign,&mut cx).map(|value|value.map(JobOutcomeBorrow::into_descriptor)));assert!(value.is_err());assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),Default::default());}
    let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let(value,heap)=observed(||publication.advance_from_fault(&fault,&mut cx).unwrap().map(JobOutcomeBorrow::into_descriptor));let progress=cx.retained_progress();physical(progress,heap,grant);assert_eq!(progress.copied_items,1);copied+=progress.copied_bytes;born+=heap.0;released+=heap.1;descriptor=value;turns+=1;assert!(turns<100000);assert_eq!(std::ptr::addr_of!(publication),original_header);assert_eq!(publication.buffer.as_ptr(),window_pointer);assert_eq!(std::ptr::addr_of!(fault),fault_pointer);assert_eq!(fault.message.as_ptr(),text_pointer);
   }
   if let Some(mut descriptor)=descriptor{let(view,heap)=observed(||publication.borrow_outcome(&descriptor).unwrap());assert_eq!(heap,(0,0));let payload=match view{JobOutcomeView::Fault{detail,..}=>detail,_=>panic!("same canonical Fault view required")};let native_payload=payload as*const _;assert_eq!(publication.published().unwrap()as*const _,native_payload);let mut bytes=Vec::with_capacity(payload.len());for index in 0..payload.page_count(){bytes.extend_from_slice(payload.page(index).unwrap());}assert_eq!(serde_json::from_slice::<serde_json::Value>(&bytes).unwrap(),row["expected"]);assert_eq!(copied,bytes.len()*2);let(step,heap)=observed(||descriptor.acknowledge(RetainedCloneGrant{maximum_items:0,..grant}));assert_eq!(heap,(0,0));assert_eq!(step.progress(),Default::default());assert!(!descriptor.is_acknowledged());let(step,heap)=observed(||descriptor.acknowledge(RetainedCloneGrant{maximum_copy_bytes:0,..grant}));assert_eq!(heap,(0,0));assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,..Default::default()});assert!(descriptor.is_acknowledged());let(_,heap)=observed(||drop(descriptor));assert_eq!(heap,(0,0));}
   while !publication.terminal_is_empty(){let(demand,heap)=observed(||publication.retirement_demands().unwrap());assert_eq!(heap,(0,0));for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(demand.release_bytes>0).then(||RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..grant}),(demand.depth>0).then(||RetainedCloneGrant{maximum_depth:demand.depth-1,..grant})].into_iter().flatten(){let(step,heap)=observed(||publication.close_step(denied).unwrap());assert_eq!(heap,(0,0));assert_eq!(step.progress(),Default::default());}let(step,heap)=observed(||publication.close_step(grant).unwrap());physical(step.progress(),heap,grant);born+=heap.0;released+=heap.1;}
   let(step,heap)=observed(||authority.close_step(grant).unwrap());physical(step.progress(),heap,grant);released+=heap.1;let mut cancellation=semio_framework_async::CancelTokenRetirement::from_token(cancel);while !cancellation.terminal_is_empty(){let(step,heap)=observed(||cancellation.close_step(RetainedCloneGrant{maximum_copy_bytes:0,..grant}).unwrap());physical(step.progress(),heap,grant);released+=heap.1;}let(_,heap)=observed(||{drop(publication);drop(authority);drop(cancellation)});assert_eq!(heap,(0,0));assert_eq!(born,released);assert_eq!(std::ptr::addr_of!(fault),fault_pointer);assert_eq!(fault.message.as_ptr(),text_pointer);eprintln!("[DEBUG] actual original typed Fault publication id={} cut={cut} turns={turns} copy={copied} physical={released} Fault={fault_pointer:p} window17={window_pointer:p} originalCopy17 capacity8192 metadata0 terminalDrop0",row["id"]);
  }
 }
}

